$body = '{"email":"ivan@example.com","password":"DemoPass123"}'; $r = Invoke-WebRequest -Uri http://127.0.0.1:8000/auth/login -Method Post -ContentType 'application/json' -Body $body -UseBasicParsing; $j = $r.Content | ConvertFrom-Json; $token = $j.access_token; $h = @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" }; $oid = "e955e989-dd66-44e5-ab35-fcadce50f1c3";
function get($u,$hdrs){ try { $x = Invoke-WebRequest -Uri $u -Method Get -Headers $hdrs -UseBasicParsing -ErrorAction Stop; return "$($x.StatusCode) $($x.Content)" } catch { $resp=$_.Exception.Response; if($resp){$sr=New-Object System.IO.StreamReader($resp.GetResponseStream());$b=$sr.ReadToEnd();$sr.Close();return "$($resp.StatusCode) $b"} else { return "ERR $($_.Exception.Message)" } } }
"S9.i GET order no token: $(get "http://127.0.0.1:8000/orders/$oid" $null)"
"S9.ii GET order with ivan token: $(get "http://127.0.0.1:8000/orders/$oid" $h)"
$p = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/orders/$oid/status" -Method Patch -Headers $h -Body '{"status":"confirmed"}' -UseBasicParsing -ErrorAction SilentlyContinue; "PATCH confirmed: $($p.StatusCode)"
$t = @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" }; $tr = Invoke-WebRequest -Uri "http://127.0.0.1:8000/admin/transfers" -Method Post -Headers $t -Body '{"from_warehouse_id":"55555555-5555-5555-5555-555555555003","to_warehouse_id":"55555555-5555-5555-5555-555555555004","status":"pending"}' -UseBasicParsing -ErrorAction SilentlyContinue; "POST /admin/transfers: $($tr.StatusCode)"
